let selectedEvent='Todos',selectedYear='Todos',selectedGenre='Todos',selectedArtist='Todos',search='';
const $=id=>document.getElementById(id);

async function resolveCity(lat,lon){
  try{
    const qs=new URLSearchParams({format:'jsonv2',lat:String(lat),lon:String(lon),zoom:'10','accept-language':'pt-BR'});
    const res=await fetch('https://nominatim.openstreetmap.org/reverse?'+qs.toString(),{headers:{'Accept':'application/json'}});
    if(!res.ok)throw new Error('geocode');
    const data=await res.json();
    const a=data.address||{};
    return a.city||a.town||a.village||a.municipality||a.county||a.state||'';
  }catch(e){return '';}
}
function setHeroLocation(name){
  const el=$('p54DesertCoordinate');
  if(!el)return;
  const clean=String(name||'').trim();
  el.textContent=clean?`BLACK ROCK CITY → ${clean.toUpperCase()} → O MUNDO`:'BLACK ROCK CITY → SUA FREQUÊNCIA → O MUNDO';
}
function setupHeroLocation(){
  const btn=$('p54UseLocation');
  if(!btn||!navigator.geolocation){btn&&btn.remove();return;}
  let busy=false;
  const finish=(label,done=false)=>{btn.textContent=label;btn.classList.remove('is-loading');btn.classList.toggle('is-done',done);busy=false;};
  const start=()=>new Promise(resolve=>{
    if(busy)return resolve(false);
    busy=true;btn.classList.add('is-loading');btn.textContent='LOCALIZANDO…';
    navigator.geolocation.getCurrentPosition(async pos=>{
      const city=await resolveCity(pos.coords.latitude,pos.coords.longitude);
      if(city){setHeroLocation(city);finish('LOCALIZAÇÃO ATIVA',true);}
      else{setHeroLocation(`${pos.coords.latitude.toFixed(2)}°, ${pos.coords.longitude.toFixed(2)}°`);finish('COORDENADAS ATIVAS',true);}
      resolve(true);
    },err=>{
      const denied=err&&err.code===1;
      finish(denied?'LOCALIZAÇÃO BLOQUEADA':'TENTAR NOVAMENTE');
      resolve(false);
    },{enableHighAccuracy:false,timeout:10000,maximumAge:1800000});
  });
  btn.addEventListener('click',()=>{start();});
  if(navigator.permissions&&navigator.permissions.query){
    navigator.permissions.query({name:'geolocation'}).then(status=>{
      if(status.state==='granted')start();
    }).catch(()=>{});
  }
}
function card(s){const id=encodeURIComponent(s.id);return `<article class="p54-card">
 <button type="button" class="p54-card-art" data-p54-video="${safe(s.id)}" aria-label="Assistir ${safe(s.title)} no player flutuante">
  <img src="${safe(s.cover)}" alt="${safe(s.artist)} em ${safe(s.event)}" loading="lazy"><span class="p54-play"><svg class="pulso-svg-play" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8.3 5.4c0-.72.79-1.16 1.41-.79l10.17 6.59a.95.95 0 0 1 0 1.6L9.71 19.4c-.62.4-1.41-.05-1.41-.79V5.4Z" fill="currentColor"/></svg></span><span class="p54-card-year">${s.year}</span></button>
 <div class="p54-card-info"><span class="p54-genre">${safe(s.event)} · ${safe(s.genre)}</span><h3>${safe(s.title)}</h3>
 <p>${safe(s.description)}</p><div class="p54-card-actions"><button type="button" data-p54-video="${safe(s.id)}"><svg class="pulso-svg-play" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8.3 5.4c0-.72.79-1.16 1.41-.79l10.17 6.59a.95.95 0 0 1 0 1.6L9.71 19.4c-.62.4-1.41-.05-1.41-.79V5.4Z" fill="currentColor"/></svg> ASSISTIR NO PULSO</button>
 <a href="${safe(s.url)}" target="_blank" rel="noopener noreferrer">YOUTUBE ↗</a></div></div></article>`;}
function filtered(){return sets.filter(s=>{
 const passEvent=selectedEvent==='Todos'||s.event===selectedEvent;
 const passArtist=selectedArtist==='Todos'||norm(s.artist).includes(norm(selectedArtist));
 const passYear=selectedYear==='Todos'||String(s.year)===selectedYear||(selectedYear==='Clássicos'&&s.year<2025);
 const passGenre=selectedGenre==='Todos'||norm(s.genre).includes(norm(selectedGenre));
 const passSearch=!search||norm([s.artist,s.title,s.event,s.genre,s.year].join(' ')).includes(norm(search));
 return passEvent&&passYear&&passGenre&&passSearch&&passArtist;
 });}
function render(){const grid=$('p54Grid');if(!grid)return;const list=filtered();
 let archivesNode=$('p54OfficialPlaylists');
 if(!archivesNode){archivesNode=document.createElement('section');archivesNode.id='p54OfficialPlaylists';archivesNode.className='p54-official-playlists';archivesNode.setAttribute('aria-label','Arquivos oficiais de sets do Tomorrowland');grid.before(archivesNode);}
 const showArchives=(selectedEvent==='Todos'||selectedEvent==='Tomorrowland')&&selectedGenre==='Todos'&&!search.trim();
 const visibleArchives=showArchives?festivalPlaylists.filter(p=>selectedYear==='Todos'||String(p.year)===selectedYear):[];
 archivesNode.hidden=visibleArchives.length===0;
 archivesNode.innerHTML=visibleArchives.length?'<div class="p54-archives-intro"><span>ARQUIVO DO FESTIVAL</span><strong>TOMORROWLAND · PLAYLISTS COMPLETAS</strong><p>Explore as coleções oficiais publicadas pelo Tomorrowland no YouTube. Os vídeos permanecem nos canais originais.</p></div><div class="p54-archives-grid">'+visibleArchives.map(p=>'<a class="p54-archive-link" href="'+safe(p.url)+'" target="_blank" rel="noopener noreferrer"><span class="p54-archive-overline">PLAYLIST NO YOUTUBE · '+p.year+'</span><strong>'+safe(p.title)+'</strong><small>'+safe(p.subtitle)+'</small><span class="p54-archive-go">ABRIR COLEÇÃO ↗</span></a>').join('')+'</div>':'';
grid.innerHTML=list.length?list.map(card).join(''):'<div class="p54-empty">Nenhum set corresponde a esses filtros. Tente outro evento ou estilo.</div>';
 const counter=$('p54Count');if(counter)counter.textContent=`${list.length} SET${list.length===1?'':'S'} · YOUTUBE OFICIAL`;
 document.querySelectorAll('[data-p54-event]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.p54Event===selectedEvent)));
 document.querySelectorAll('[data-p54-year]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.p54Year===selectedYear)));
 document.querySelectorAll('[data-p54-artist]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.p54Artist===selectedArtist)));
 document.querySelectorAll('[data-p54-genre]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.p54Genre===selectedGenre)));
}
function setCatalogExpanded(expanded){const section=$('p54Catalog'),button=$('p54ExpandCatalog');if(!section||!button)return;section.classList.toggle('p54-catalog-expanded',expanded);button.setAttribute('aria-expanded',String(expanded));button.innerHTML=expanded?'MOSTRAR MENOS SETS <span aria-hidden="true">−</span>':'VER TODOS OS SETS <span aria-hidden="true">＋</span>';}
function pickEvent(event){setCatalogExpanded(true);selectedEvent=event;selectedArtist='Todos';selectedYear='Todos';selectedGenre='Todos';render();$('p54Catalog')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}
function renderRanking(){const el=$('p54Djs');if(!el)return;el.innerHTML=ranking.map((artist,i)=>{const l=djInstagram({artist}),p=rankedPhotos[i];return `<div class="p54-rank"><strong>${String(i+1).padStart(2,'0')}</strong><span class="p54-rank-avatar" title="Imagem: ${safe(p.credit)}"><img loading="lazy" decoding="async" src="${safe(p.src)}" alt="Foto de ${safe(artist)}" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="p54-avatar-fallback" hidden>${safe(artist).slice(0,2).toUpperCase()}</span></span><span class="p54-rank-name">${safe(artist)}</span><a href="${safe(l)}" target="_blank" rel="noopener noreferrer" aria-label="Instagram de ${safe(artist)}">IG ↗</a></div>`}).join('');}
function renderClubRanking(){const el=$('p54Clubs');if(!el)return;el.innerHTML=clubs2026.map(c=>`<article class="p54-club-card"><div class="p54-club-picture"><img loading="lazy" decoding="async" src="${safe(c.img)}" alt="Foto de ${safe(c.name)}" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="p54-club-fallback" hidden>${safe(c.name)}</span><strong>#${c.rank}</strong></div><div class="p54-club-info"><h3>${safe(c.name)}</h3><p>${safe(c.location)}</p><small class="p54-photo-credit">Foto: ${safe(c.source)}</small><a href="https://djmag.com/top100clubs/2026" target="_blank" rel="noopener noreferrer">VER NA DJ MAG ↗</a></div></article>`).join('');}
